-- Read-only current-state application schema export. No application/Auth/Storage rows.
-- Deliberately excludes managed schema DDL and extension-owned objects.
with app_rel as (
 select c.*,n.nspname from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','S','f')
 and not exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e')
), app_proc as (
 select p.*,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname in ('public','private') and p.prokind in ('f','p')
 and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')
)
select jsonb_build_object(
 'format_version',1,'captured_at',now(),'server_version',current_setting('server_version'),
 'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) order by nspname) from pg_namespace where nspname in ('public','private')),
 'extensions',(select jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
 'enums',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'labels',(select jsonb_agg(enumlabel order by enumsortorder) from pg_enum where enumtypid=t.oid)) order by n.nspname,t.typname),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private') and t.typtype='e'),
 'other_types',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype)),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private') and t.typtype in ('d','r') and not exists(select 1 from pg_depend d where d.classid='pg_type'::regclass and d.objid=t.oid and d.deptype='e')),
 'relations',(select jsonb_agg(jsonb_build_object('schema',nspname,'name',relname,'kind',relkind,'persistence',relpersistence,'owner',pg_get_userbyid(relowner),'acl',relacl::text,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'options',reloptions,'definition',case when relkind in ('v','m') then pg_get_viewdef(oid,false) else null end) order by nspname,relname) from app_rel),
 'columns',(select jsonb_agg(jsonb_build_object('schema',c.nspname,'table',c.relname,'name',a.attname,'ordinal',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(ad.adbin,ad.adrelid),'collation',case when a.attcollation<>t.typcollation then a.attcollation::regcollation::text else null end,'acl',a.attacl::text) order by c.nspname,c.relname,a.attnum) from app_rel c join pg_attribute a on a.attrelid=c.oid join pg_type t on t.oid=a.atttypid left join pg_attrdef ad on ad.adrelid=c.oid and ad.adnum=a.attnum where a.attnum>0 and not a.attisdropped),
 'constraints',(select jsonb_agg(jsonb_build_object('schema',c.nspname,'table',c.relname,'name',p.conname,'type',p.contype,'definition',pg_get_constraintdef(p.oid,false),'validated',p.convalidated) order by c.nspname,c.relname,p.conname) from pg_constraint p join app_rel c on c.oid=p.conrelid),
 'indexes',(select jsonb_agg(jsonb_build_object('schema',c.nspname,'table',c.relname,'name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'constraint_backed',exists(select 1 from pg_constraint p where p.conindid=i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) order by c.nspname,c.relname,ic.relname) from pg_index i join app_rel c on c.oid=i.indrelid join pg_class ic on ic.oid=i.indexrelid),
 'sequences',(select coalesce(jsonb_agg(jsonb_build_object('schema',c.nspname,'name',c.relname,'type',format_type(s.seqtypid,null),'start',s.seqstart,'increment',s.seqincrement,'min',s.seqmin,'max',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle)),'[]') from pg_sequence s join app_rel c on c.oid=s.seqrelid),
 'functions',(select jsonb_agg(jsonb_build_object('schema',nspname,'name',proname,'args',pg_get_function_identity_arguments(oid),'owner',pg_get_userbyid(proowner),'acl',proacl::text,'definition',pg_get_functiondef(oid),'md5',md5(pg_get_functiondef(oid))) order by nspname,proname,pg_get_function_identity_arguments(oid)) from app_proc),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,false)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace fn on fn.oid=p.pronamespace where not t.tgisinternal and (n.nspname in ('public','private') or (n.nspname in ('auth','storage') and fn.nspname in ('public','private')))),
 'policies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'cmd',cmd,'using',qual,'with_check',with_check) order by schemaname,tablename,policyname) from pg_policies where schemaname in ('public','private','storage')),
 'grants',(select jsonb_agg(jsonb_build_object('schema',c.nspname,'name',c.relname,'kind',c.relkind,'grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by c.nspname,c.relname,a.grantee,a.privilege_type) from app_rel c cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) a),
 'function_grants',(select jsonb_agg(jsonb_build_object('schema',p.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by p.nspname,p.proname,pg_get_function_identity_arguments(p.oid),a.grantee) from app_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a),
 'default_grants',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'object_type',d.defaclobjtype,'grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a where n.nspname in ('public','private') or d.defaclnamespace=0),
 'view_dependencies',(select jsonb_agg(distinct jsonb_build_object('schema',v.nspname,'view',v.relname,'depends_schema',n.nspname,'depends',r.relname)) from app_rel v join pg_rewrite w on w.ev_class=v.oid join pg_depend d on d.classid='pg_rewrite'::regclass and d.objid=w.oid join pg_class r on r.oid=d.refobjid join pg_namespace n on n.oid=r.relnamespace where v.relkind in ('v','m') and r.oid<>v.oid),
 'publications',(select coalesce(jsonb_agg(jsonb_build_object('publication',pubname,'all_tables',puballtables,'insert',pubinsert,'update',pubupdate,'delete',pubdelete,'truncate',pubtruncate)),'[]') from pg_publication),
 'publication_tables',(select coalesce(jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename)),'[]') from pg_publication_tables where schemaname in ('public','private'))
) as snapshot;
